import pytest


class BadInput(Exception):
    def __init__(self, text: str) -> None:
        super().__init__(text)
        self.text = text


def sum_parsed(xs: list[str]) -> int:
    """Parse every string as an integer and return their sum.

    Raises BadInput with the offending text for the first invalid integer string.
    """
    total = 0
    for s in xs:
        try:
            total += int(s)
        except ValueError:
            raise BadInput(s) from None
    return total


def test_sum_parsed_empty() -> None:
    assert sum_parsed([]) == 0


def test_sum_parsed_valid() -> None:
    assert sum_parsed(["1", "2", "3"]) == 6
    assert sum_parsed(["-5", "10", "0"]) == 5


def test_sum_parsed_invalid_raises_bad_input() -> None:
    with pytest.raises(BadInput) as exc_info:
        sum_parsed(["1", "not_a_number", "3"])
    assert exc_info.value.text == "not_a_number"


def test_sum_parsed_raises_on_first_invalid() -> None:
    with pytest.raises(BadInput) as exc_info:
        sum_parsed(["10", "first_bad", "20", "second_bad"])
    assert exc_info.value.text == "first_bad"


def test_sum_parsed_float_string_raises() -> None:
    with pytest.raises(BadInput) as exc_info:
        sum_parsed(["3.14"])
    assert exc_info.value.text == "3.14"

